sketches.source:
setcpm(84/4)

// sequence(1, 8) raises everything one degree more each bar, for eight floors, then back to the lobby
muzak: n("<[0 ~ 2 4] [5 4 2 ~]>").sequence(1, 8).scale("C:major").transpose(12)
  .s("sine").timbre("hollow").vib(5).vibdepth(.1).attack(.05).sustain(.6).release(.3)
  .room(.4).gain(.22)

// The floor ding climbs with it
ding: n("[2 0] ~ ~ ~").sequence(1, 8).scale("C:major").transpose(24)
  .s("sine").fm(2).fmh(2.76).decay(1).sustain(0).release(1).gain(.12)

// Polite bossa comping, also climbing
keys: n("[0,2,4,6]").struct("~ ~ x ~ x ~ ~ x").sequence(1, 8).scale("C:major")
  .s("triangle").timbre("soft").decay(.3).sustain(0).release(.3).pan(.4).gain(.18)

// The band panics on the top floor: the last bar of every eight plays twice as fast
drums: s("rim ~ ~ rim ~ ~ rim ~, hh*8").lastOf(8, x => x.hurry(2)).gain(.3)

// The machinery: a hum in the shaft and the cable creaking now and then
shaft: s("engine").slow(8).lpf(300).gain(.1)
cable: s("~ ~ ~ creak").mask("<0 0 1 0 0 1 0 0>").elevation(60).distance(3).gain(.12)

setcpm(96/4)

// One sentence, read aloud by the whole committee at four speeds at once
// converge shifts the copies so they all start the sentence together every eight bars
committee: n("0 2 1 3 2 4 3 1").scale("D:dorian").transpose(12)
  .s("voice").syl("<[wa ra ba la ma da na po] [mo re ko re ti me nu to]>").voicetype("tenor")
  .converge(8, 1, 9/8, 5/4, 4/3).attack(.02).release(.2).room(.4).gain(.12)

// The rare moment of consensus
consensus: note("<[d3,f3,a3,c4] ~ ~ ~ ~ ~ ~ ~>").s("choir").syl("ah")
  .attack(.2).release(2).space("hall").gain(.3)

// The chair brings the gavel down just before it
gavel: s("<~ ~ ~ ~ ~ ~ ~ [~ ~ lt lt]>").speed(1.8).lpf(2000).room(.4).gain(.5)

// Someone takes the minutes on your left; the projector hums behind you
minutes: s("click*16?0.6").hpf(2500).azimuth(-70).distance(2).seed("minutes").gain(.1)
projector: s("engine").slow(8).lpf(500).azimuth(170).distance(4).gain(.08)

// Quiet hold music under it all
bass: note("<d2 c2 bb1 c2>").s("sine").attack(.05).sustain(.6).release(.5).gain(.28)

setcpm(72/4)

// Ah... ah... ah...: three chords, each swelling higher and slower to arrive
choir: note("<[c4,e4,g4] [d4,f#4,a4] [e4,g#4,b4] ~>").s("choir").syl("ah")
  .attack("<1 1.5 2.5 0>").release(.2).space("church").gain(.3)

// The sneeze: a burst of noise and a whispered shoo
burst: s("<~ ~ ~ [white ~ ~ ~]>").hpf(1500).decay(.25).sustain(0).room(.5).gain(.3)
shoo: s("<~ ~ ~ [whisper ~ ~ ~]>").syl("shoo").gain(.4)

// Bless you, from the back row
bless: note("<~ ~ ~ [~ ~ ~ ~ ~ ~ c3 g2]>").s("voice").syl("<~ ~ ~ [~ ~ ~ ~ ~ ~ ble su]>")
  .voicetype("bass").mono(1).vglide(.05).release(.4).azimuth(150).distance(4).gain(.26)

// The organ pretends nothing happened
organ: note("<c2 d2 e2 c2>").s("sawtooth").timbre("organ").lpf(500)
  .attack(.3).sustain(.8).release(1).space("church").gain(.2)

// A tissue, pulled from the box
tissue: s("<~ ~ ~ [~ ~ ~ ~ pink ~ ~ ~]>").hpf(3000).decay(.15).sustain(0).gain(.05)

setcpm(72/4)

const tune = n("0 2 4 5 7 5 4 2").scale("E:major").transpose(12)

// subtractive plays one note fewer every bar; degradeBy forgets at random, more and more over sixteen bars
memory: tune.subtractive(8).degradeBy(env("0 .9", 16)).seed("goldfish")
  .s("triangle").timbre("glass").decay(.3).sustain(0).release(.5).room(.5).gain(.22)

// The other fish only remembers the first quarter of every bar, and keeps repeating it
friend: tune.octave(-1).linger(.25)
  .s("sine").fm(.6).fmh(4).decay(.3).sustain(0).pan(.7).gain(.16)

// The tank: bubbles rising, the filter humming, a little plastic castle
bubbles: s("drip*8?0.5").speed(rand.range(1.5, 3)).elevation(saw.range(-30, 50))
  .distance(2).seed("bubbles").gain(.1)
filter: s("brown").slow(8).lpf(300).gain(.1)
castle: note("<e2 ~ b1 ~>").s("sine").attack(.5).sustain(.8).release(2).gain(.24)

setcpm(80/4)

const subject = n("<[0 2 4 7] [5 4 2 0]>")

// A: as written. B: upside down. C: backwards. D: upside down and backwards
lead: form("A@4 B@4 C@4 D@4", subject, subject.invert(4), subject.retro(2), subject.invert(4).retro(2))
  .scale("F:major").transpose(12)
  .s("sine").timbre("hollow").vib(5).vibdepth(.1).attack(.04).sustain(.6).release(.3)
  .room(.5).gain(.22)

// Raindrops falling up: a pitch envelope that rises, and an elevation that climbs past your ears
drops: note("c5*8?0.5").s("sine").penv(-24).pdecay(.15).decay(.15).sustain(0)
  .elevation(saw.range(-60, 80)).azimuth(rand.range(-90, 90)).distance(2)
  .seed("updraft").gain(.12)

// The drums, in reverse
drums: s("bd ~ [~ bd] ~, ~ sd ~ [sd sd], hh*8").rev().gain(.4)

// A pad floating up out of reach
pad: note("<[f3,a3,c4] [bb2,d3,f3] [c3,e3,g3] [f3,a3,c4]>").s("sawtooth").unison(3).detune(.2)
  .elevation(40).distance(3).attack(1).release(2).lpf(1400).room(.6).gain(.12)

setcpm(96/4)

// Six saucepans, highest first: metallic FM inside a can body, ringing plain hunt
pans: note("g5 e5 d5 c5 a4 g4").ring("plainhunt", 6)
  .s("sine").fm(5).fmh(1.41).decay(.8).sustain(0).release(.8)
  .body("can").bodymix(.5).room(.4).gain(.2)

// Wooden spoons on four pots, in a different ordering each bar
spoons: s("rim lt mt ht").permute(4, "<0 7 13 22>").speed(1.4).lpf(3000).gain(.3)

// The fridge hums with a whistling overtone
fridge: note("b1").slow(8).s("hum").overtone(5).gain(.12)

// The blender joins in every fourth bar
blender: s("engine").slow(2).lpf(2500).mask("<0 0 0 1>").gain(.1)

// A low pot for a bass, and the oven clock
bass: note("<c2 g1 a1 f1>").s("sine").fm(1.2).fmh(1.5).decay(.6).sustain(.2).gain(.3)
clock: s("tick*4").gain(.06)

setcpm(112/4)

// Rubber stamps in a cycle of seven, typewriters in a cycle of eleven, sharing one step size
stamps: s("{lt ~ lt lt ~ lt ~}%8").speed(1.5).lpf(1500).azimuth(-40).distance(2).gain(.4)
typewriter: s("{click click click click click click click click click click tick}%16")
  .hpf(2000).azimuth(50).distance(2).gain(.14)

// The carriage-return bell
return: note("<~ ~ ~ [~ ~ ~ c6]>").s("sine").fm(3).fmh(3.5).decay(.8).sustain(0).azimuth(50).gain(.12)

// The phone rings and rings, and nobody answers
phone: note("<[e5,g5] ~ [e5,g5] ~>").s("sine").trem(20).tremdepth(1)
  .sustain(1).release(.05).azimuth(110).distance(4).gain(.06)

// Hold music, crushed and heard through the wall
hold: n("<[0 2 4 2] [3 2 1 ~]>").scale("A:minor").transpose(12).s("square").pw(.3)
  .crush(6).occlude(.6).decay(.2).sustain(.4).gain(.14)

// The clerk calls next, and the buzzer rejects your form every eight bars
clerk: note("<~ [a3 e3] ~ ~>").s("voice").syl("<~ [nek sto] ~ ~>").voicetype("alto")
  .release(.3).distance(3).gain(.24)
buzzer: note("c2").s("square").mask("<0 0 0 0 0 0 0 1>").lpf(900).sustain(1).gain(.12)

setcpm(60/4)

// The universe, played once: eight bars of stars, eight of dust, eight of almost nothing
const stars = n("0 2 4 7 9 7 4 2").scale("C:major pentatonic").transpose(12)
light: form("A@8 B@8 C@8", stars, stars.slow(2).degradeBy(.4), stars.slow(8).degradeBy(.8)).once()
  .s("triangle").timbre("glass").decay(.4).sustain(0).release(1.5)
  .room(.8).size(.95).seed("entropy").gain(.18)

// The pad cools over twenty-four bars: its filter closes as it fades
pad: note("<[c3,g3,e4] [a2,e3,c4] [f2,c3,a3] [g2,d3,b3]>").s("sawtooth").unison(3).detune(.2)
  .lpf(env("2400 200", 24)).attack(1).release(2).room(.7).gain(.12).fadeout(8, 16).exit(24)

// Background radiation: the noise spreads from one point in your head to everywhere
radiation: s("pink").icorr(env("1 0", 24)).hpf(1000).lpf(4000).gain(.03).exit(28)

// The last protons decaying, fewer and fewer
protons: s("click*16").degradeBy(env(".5 1", 24)).hpf(3000)
  .azimuth(rand.range(-180, 180)).distance(4).seed("protons").gain(.1).exit(24)

// The void hums: a 2 Hz binaural drone, below the 3-30 Hz warning range, then nothing at all
nothing: note("[c1,g1]").s("sine").binaural(2).attack(4).sustain(1).release(6)
  .enter(8).gain(.2).fadeout(8, 24).exit(32)
